      return (IEnumerator)(this.GetEnumerator());
    }

    
    
    /// <summary>
    /// Supports simple iteration over a <see cref="LevelCollection"/>.
    /// </summary>
    private sealed class Enumerator : IEnumerator, ILevelCollectionEnumerator
    {
      
