  /// <summary>
  /// The return result from <see cref="IFilter.Decide"/>
  /// </summary>
  /// <remarks>
  /// <para>
  /// The return result from <see cref="IFilter.Decide"/>
  /// </para>
  /// </remarks>
  public enum FilterDecision : int
  {
    /// <summary>
    /// The log event must be dropped immediately without 
    /// consulting with the remaining filters, if any, in the chain.
    /// </summary>
    Deny = -1,

    /// <summary>
