    /// </remarks>
    /// <seealso cref="M:Debug(object)"/>
    /// <seealso cref="IsDebugEnabled"/>
    void DebugFormat(string format, object arg0, object arg1, object arg2);

    /// <summary>
    /// Logs a formatted message string with the <see cref="Level.Debug"/> level.
