namespace log4net.Layout
{

    using global::System;
    using global::System.IO;
    using global::System.Text;
    using global::log4net.Util;
    using global::log4net.Core;
  /// <summary>
  /// A very simple layout
  /// </summary>
  /// <remarks>
  /// <para>
  /// SimpleLayout consists of the level of the log statement,
  /// followed by " - " and then the log message itself. For example,
  /// <code>
  /// DEBUG - Hello world
  /// </code>
  /// </para>
  /// </remarks>
  /// <author>Nicko Cadell</author>
  /// <author>Gert Driesen</author>
  public class SimpleLayout : LayoutSkeleton
  {
    
    /// <summary>
    /// Constructs a SimpleLayout
    /// </summary>
    public SimpleLayout()
    {
      IgnoresException = true;
    }

    
    
    /// <summary>
    /// Initialize layout options
    /// </summary>
    /// <remarks>
    /// <para>
    /// This is part of the <see cref="IOptionHandler"/> delayed object
    /// activation scheme. The <see cref="ActivateOptions"/> method must 
    /// be called on this object after the configuration properties have
    /// been set. Until <see cref="ActivateOptions"/> is called this
    /// object is in an undefined state and must not be used. 
    /// </para>
    /// <para>
    /// If any of the configuration properties are modified then 
    /// <see cref="ActivateOptions"/> must be called again.
    /// </para>
    /// </remarks>
    public override void ActivateOptions()
    {
      // nothing to do.
    }

    
    
    /// <summary>
    /// Produces a simple formatted output.
    /// </summary>
    /// <param name="loggingEvent">the event being logged</param>
    /// <param name="writer">The TextWriter to write the formatted event to</param>
    /// <remarks>
    /// <para>
    /// Formats the event as the level of the even,
    /// followed by " - " and then the log message itself. The
    /// output is terminated by a newline.
    /// </para>
    /// </remarks>
    public override void Format(TextWriter writer, LoggingEvent loggingEvent)
    {
      if (loggingEvent == null)
      {
        throw new ArgumentNullException("loggingEvent");
      }

      writer.Write(loggingEvent.Level.DisplayName);
      writer.Write(" - ");
      loggingEvent.WriteRenderedMessage(writer);
      writer.WriteLine();
    }

      }

}

